# --- map change guard (Moonshot compatibility patch, r5) -----------------------------------------
# Digi-Jack clones live in the persistent Loader level, so a map change does not take them away. A
# clone still waiting out its de-rez (DEREZ_SECONDS) when the player walked into a level exit was
# killed during the transition, where the level no longer ticks, so its body was never removed and
# the new map never finished loading (2026-09-23: cast, walk through an exit -> endless loading
# screen; no cast -> loads at once). A map change is now held until every clone is gone and then
# replayed; one that starts where these hooks do not see it finishes the clones on its first tick.
_world_seen: tuple | None = None
_travel_hold: dict | None = None        # {"func", "kwargs", "since", "by"} while a map change waits
_travel_releasing = False
TRAVEL_HOLD_MAX = 4.0                   # seconds: the player is never kept from travelling longer


def _world_changed(obj: UObject) -> bool:
    """True on the first tick on a different map. BL2 streams every map into the persistent Loader
    level, so WorldInfo and its clock survive a map change; the map name tells them apart."""
    global _world_seen
    try:
        wi = obj.WorldInfo
        now = (str(wi.GetMapName(True) or "").lower(), wi._get_address(), float(wi.TimeSeconds))
    except Exception:  # noqa: BLE001
        return False
    before, _world_seen = _world_seen, now
    return before is not None and (now[0] != before[0] or now[1] != before[1] or now[2] < before[2])


def _clones_outstanding() -> int:
    """Clones not yet removed: tracked, queued, or killed and still standing."""
    n = len(_clones) + len(_pending_cleanup)
    for path in list(_zombies):
        pawn = _resolve_pawn(path)
        try:
            if pawn is not None and not bool(pawn.bDeleteMe):
                n += 1
        except Exception:  # noqa: BLE001
            pass
    return n


def _finish_clones_now(reason: str) -> None:
    """Every clone straight to the clean-up queue without the de-rez wait. The drain still takes one
    per tick: two destroyed in one frame is what the old crashes landed on."""
    if _clones:
        _clear_clone_masters(reason)
        _queue_cleanup_all(reason)
    for path in _pending_cleanup:
        _pending_not_before[path] = 0.0


def _travel_kwargs(args: WrappedStruct) -> dict:
    out = {}
    for prop in args._type._properties():
        name = str(prop.Name)
        if name == "ReturnValue":
            continue
        try:
            out[name] = getattr(args, name)
        except Exception:  # noqa: BLE001
            pass
    return out


def _hold_travel(args: WrappedStruct, func: BoundFunction, by: str):
    global _travel_hold
    if _travel_releasing:
        return None
    if _travel_hold is not None:
        return Block                            # the same map change asked again while it waits
    try:
        n = _clones_outstanding()
    except Exception:  # noqa: BLE001
        return None
    if not n:
        return None
    try:
        kwargs = _travel_kwargs(args)
    except Exception:  # noqa: BLE001
        unrealsdk.logging.error("[Doppelganger] map change: arguments unreadable, not held: " + traceback.format_exc().splitlines()[-1])
        return None
    _finish_clones_now("map change")
    _travel_hold = {"func": func, "kwargs": kwargs, "since": time.monotonic(), "by": by}
    unrealsdk.logging.info(f"[Doppelganger] map change ({by}) held: removing {n} clone(s) first")
    return Block


def _release_travel_if_ready() -> None:
    global _travel_hold, _travel_releasing
    held = _travel_hold
    if held is None:
        return
    waited = time.monotonic() - held["since"]
    left = _clones_outstanding()
    if left and waited < TRAVEL_HOLD_MAX:
        return
    _travel_hold = None
    unrealsdk.logging.info(f"[Doppelganger] map change ({held['by']}) released after {waited:.1f}s"
                           + (f"; {left} clone(s) still standing" if left else ""))
    _travel_releasing = True
    try:
        held["func"](**held["kwargs"])
    except Exception:  # noqa: BLE001
        unrealsdk.logging.error("[Doppelganger] map change replay failed: " + traceback.format_exc().splitlines()[-1])
    finally:
        _travel_releasing = False


@hook("Engine.WorldInfo:ServerTravel", Type.PRE, hook_identifier="doppel_compat_hold_servertravel")
def _hold_server_travel(obj: UObject, args: WrappedStruct, ret: None, func: BoundFunction):
    return _hold_travel(args, func, "WorldInfo.ServerTravel")


@hook("Engine.GameInfo:ProcessServerTravel", Type.PRE, hook_identifier="doppel_compat_hold_processtravel")
def _hold_process_travel(obj: UObject, args: WrappedStruct, ret: None, func: BoundFunction):
    return _hold_travel(args, func, "GameInfo.ProcessServerTravel")


@hook("Engine.PlayerController:ClientTravel", Type.PRE, hook_identifier="doppel_compat_hold_clienttravel")
def _hold_client_travel(obj: UObject, args: WrappedStruct, ret: None, func: BoundFunction):
    return _hold_travel(args, func, "PlayerController.ClientTravel")

_step("reap")
if not _paused:
    _reap_zombies()
else:
    for _z in _zombies.values():   # the watch restarts once the new map is up
        _z["deadline"] = max(_z["deadline"], time.monotonic() + 0.5)
